assert_eq "pr: headRefName from head.ref (9003)" "computing-branch" "$(jq -r '.headRefName' <<<"$pv3")"
# Absent labels in raw REST → empty array (// [] path), not null.
assert_eq "pr: absent labels → empty array" "0" "$(jq '.labels | length' <<<"$pv3")"
