STUB_DIR="$(cd "$(dirname "$0")" && pwd)/stub"
printf '%s\n' "${DISPATCH_FIND_PR_RETRY_DELAY:-unset}" > "$STUB_DIR/find-pr-delay-seen.txt"
exit 0
PROBE
chmod +x "$TMPDIR_TEST/dispatch-find-pr"
