exit 1
GIT_STUB
chmod +x "$_rpr_stub/git"
if result=$(PATH="$_rpr_stub:$SAVED_PATH" bash -c '
  source "'"$SCRIPT_DIR"'/lib.sh"
  resolve_project_root
'); then rc=0; else rc=$?; fi
