if (( out >= 1 )); then
  PASS=$((PASS + 1)); echo "  PASS: r=1 terminal_seg W=90; used_weekly=88 under pace → N=$out (>=1)"
else
  FAIL=$((FAIL + 1)); echo "  FAIL: r=1 used_weekly=88 expected N>=1 (W=90), got $out"
fi
