echo "Test: a positional argument exits 2 and launches nothing"
sw_setup
rc=0
err=$("$TMPDIR_TEST/scripts/dispatch-spawn-sweep" foo 2>&1 1>/dev/null) || rc=$?
assert_eq "bad-arg: dispatch-spawn-sweep exits 2" "2" "$rc"
