# --- Test: open non-newline stdin → hook returns fast (no 1s read stall) (#1519) ---
echo "Test: strip hook open non-newline stdin → returns fast, still strips label"
ohs_setup
echo "123-foo-bar" > "$STUB_DIR/current-branch.txt"
echo "456" > "$STUB_DIR/find-pr-output"
timeout 0.5 "$TMPDIR_TEST/hooks/dispatch-office-hours-strip.sh" \
  < <(printf '%s' '{"some":"payload"}'; sleep 1) \
  >/dev/null 2>&1
rc=$?
TOTAL=$((TOTAL + 1))
if [[ "$rc" -ne 124 ]]; then
  PASS=$((PASS + 1)); echo "  PASS: strip open-stdin: hook completed before the 0.5s timeout (no 1s read stall)"
else
  FAIL=$((FAIL + 1)); echo "  FAIL: strip open-stdin: hook killed at 0.5s — read is still stalling"
fi
# Correctness: the payload is drain-only, so assert the strip still fired.
api_delete_log=$(cat "$STUB_DIR/gh-api-delete.log" 2>/dev/null || true)
TOTAL=$((TOTAL + 1))
if [[ "$api_delete_log" == *"api -X DELETE repos/{owner}/{repo}/issues/456/labels/dispatch:office-hours"* ]]; then
  PASS=$((PASS + 1)); echo "  PASS: strip open-stdin: REST DELETE issues/456/labels (PR) still invoked (drain did not break strip)"
else
  FAIL=$((FAIL + 1)); echo "  FAIL: strip open-stdin: REST DELETE issues/456/labels (PR) NOT invoked (drain broke strip)"
  echo "    api-delete-log: $api_delete_log"
fi
TOTAL=$((TOTAL + 1))
if [[ "$api_delete_log" == *"api -X DELETE repos/{owner}/{repo}/issues/123/labels/dispatch:office-hours"* ]]; then
  PASS=$((PASS + 1)); echo "  PASS: strip open-stdin: REST DELETE issues/123/labels (issue) still invoked (drain did not break strip)"
else
  FAIL=$((FAIL + 1)); echo "  FAIL: strip open-stdin: REST DELETE issues/123/labels (issue) NOT invoked (drain broke strip)"
  echo "    api-delete-log: $api_delete_log"
fi
ohs_teardown

# ============================================================================
# dispatch-stop hook tests
# ============================================================================
echo ""
echo "=== dispatch-stop ==="
#
# dispatch-stop is now the graph-native node-worker Stop-hook: an escalation-park
# BACKSTOP only. tactic-dispatch-legacy-rewire Unit 3 DELETED the legacy
# <N>-<slug> issue-worker disposition (the phase-completed marker read, the
# dispatch-phase CURRENT_PHASE derivation, the dispatch:office-hours label parks
# via dispatch-apply-office-hours, the phase-advance self-close, and the
# Stop-hook tick-spawn) — those paths were reachable only for a legacy issue
# worker spawned by dispatch-materialize-spawn -> dispatch-launch-worker, both
# deleted with the legacy gh-issue lane.
#
# Surviving contract:
#   - CLAUDE_JOB_DIR unset, or state.json absent  -> no-op (exit 0).
#   - The job is a graph node worker iff state.json .name is a node id AND
#     intentions/<name>.md exists at the hook root (= <hook-dir>/../..). Only
#     then, and only when a non-empty office-hours-reason marker is present in
#     the job dir, park the node via
#     packages/intentionsutil/scripts/park-node <id> <reason> [<reco>].
#   - Any other name (a dispatch-<id> router, a stray non-node name), or a node
#     worker with no office-hours-reason marker -> no-op (exit 0).
#   - Best-effort: a park-node failure is logged to stderr and the hook still
#     exits 0 (it must never block session teardown).
#
# Harness: the hook is copied to $ROOT/.claude/hooks/dispatch-stop.sh so its
# `$(dirname)/../..` root resolves to $ROOT; the intention nodes and a fake
# park-node (recording each invocation's argv to $ROOT/park-calls.log) sit under
# $ROOT. The job dir carries state.json and the optional office-hours markers.

stopnc_setup() {
  TMPDIR_TEST=$(mktemp -d)
  ROOT="$TMPDIR_TEST/root"
  JOB_DIR="$TMPDIR_TEST/job"
  mkdir -p "$ROOT/.claude/hooks" "$ROOT/intentions" \
    "$ROOT/packages/intentionsutil/scripts" "$JOB_DIR"
  cp "$HOOK_SCRIPT_DIR/dispatch-stop.sh" "$ROOT/.claude/hooks/dispatch-stop.sh"
  chmod +x "$ROOT/.claude/hooks/dispatch-stop.sh"
  # Fake park-node: append every invocation's argv (one line per call) to
  # park-calls.log at $ROOT, and honor an optional park-exit override so a test
  # can drive the best-effort failure branch.
  cat > "$ROOT/packages/intentionsutil/scripts/park-node" <<'FAKE'
#!/usr/bin/env bash
_root="$(cd "$(dirname "$0")/../../.." && pwd)"
printf '%s\n' "$*" >> "$_root/park-calls.log"
if [[ -f "$_root/park-exit" ]]; then exit "$(cat "$_root/park-exit")"; fi
exit 0
FAKE
  chmod +x "$ROOT/packages/intentionsutil/scripts/park-node"
  : > "$ROOT/park-calls.log"
}

stopnc_teardown() {
  rm -rf "$TMPDIR_TEST"
  TMPDIR_TEST=""
}

# stopnc_state <name> — write state.json naming this job.
stopnc_state() { printf '{"name":"%s"}\n' "$1" > "$JOB_DIR/state.json"; }

# stopnc_run — run the hook with CLAUDE_JOB_DIR=$JOB_DIR; capture rc.
stopnc_run() {
  local rc=0
  ( export CLAUDE_JOB_DIR="$JOB_DIR"; "$ROOT/.claude/hooks/dispatch-stop.sh" </dev/null ) || rc=$?
  echo "$rc"
}

# --- no CLAUDE_JOB_DIR → no-op ----------------------------------------------
echo "Test: dispatch-stop no CLAUDE_JOB_DIR → no-op, park-node not called"
stopnc_setup
rc=0
( unset CLAUDE_JOB_DIR; "$ROOT/.claude/hooks/dispatch-stop.sh" </dev/null ) || rc=$?
assert_eq "stop: no CLAUDE_JOB_DIR → exit 0" "0" "$rc"
assert_eq "stop: no CLAUDE_JOB_DIR → park-node not called" "0" "$(wc -l < "$ROOT/park-calls.log")"
stopnc_teardown

# --- state.json absent → no-op ----------------------------------------------
echo "Test: dispatch-stop state.json absent → no-op, park-node not called"
stopnc_setup
rc=$(stopnc_run)   # JOB_DIR has no state.json
assert_eq "stop: no state.json → exit 0" "0" "$rc"
assert_eq "stop: no state.json → park-node not called" "0" "$(wc -l < "$ROOT/park-calls.log")"
stopnc_teardown

# --- router name (no intention node) → no-op --------------------------------
echo "Test: dispatch-stop router name (no intentions/<name>.md) → no-op"
stopnc_setup
stopnc_state "dispatch-ab12cd34"
printf 'stalled somewhere\n' > "$JOB_DIR/office-hours-reason"
rc=$(stopnc_run)
assert_eq "stop: router name → exit 0" "0" "$rc"
assert_eq "stop: router name → park-node not called" "0" "$(wc -l < "$ROOT/park-calls.log")"
stopnc_teardown

# --- node worker + no office-hours-reason → no-op ----------------------------
echo "Test: dispatch-stop node worker with no office-hours-reason → no park"
stopnc_setup
stopnc_state "tactic-some-node"
: > "$ROOT/intentions/tactic-some-node.md"
rc=$(stopnc_run)   # no office-hours-reason marker written
assert_eq "stop: node clean exit → exit 0" "0" "$rc"
assert_eq "stop: node clean exit → park-node not called" "0" "$(wc -l < "$ROOT/park-calls.log")"
stopnc_teardown

# --- node worker + office-hours-reason (no recommendation) → park ------------
echo "Test: dispatch-stop node worker + office-hours-reason → park-node <id> <reason>"
stopnc_setup
stopnc_state "tactic-some-node"
: > "$ROOT/intentions/tactic-some-node.md"
printf 'needs a human decision' > "$JOB_DIR/office-hours-reason"
rc=$(stopnc_run)
assert_eq "stop: node park → exit 0" "0" "$rc"
assert_eq "stop: node park → park-node called once" "1" "$(wc -l < "$ROOT/park-calls.log")"
assert_eq "stop: node park → argv is <id> <reason>" \
  "tactic-some-node needs a human decision" "$(cat "$ROOT/park-calls.log")"
stopnc_teardown

# --- node worker + reason + recommendation → park with 3rd arg ---------------
echo "Test: dispatch-stop node worker + reason + recommendation → park-node <id> <reason> <reco>"
stopnc_setup
stopnc_state "tactic-some-node"
: > "$ROOT/intentions/tactic-some-node.md"
printf 'needs a human decision' > "$JOB_DIR/office-hours-reason"
printf 'try approach X' > "$JOB_DIR/office-hours-recommendation"
rc=$(stopnc_run)
assert_eq "stop: node park+reco → exit 0" "0" "$rc"
assert_eq "stop: node park+reco → argv carries the recommendation" \
  "tactic-some-node needs a human decision try approach X" "$(cat "$ROOT/park-calls.log")"
stopnc_teardown

# --- best-effort: park-node failure still exits 0 ---------------------------
echo "Test: dispatch-stop park-node failure is non-fatal (hook still exits 0)"
stopnc_setup
stopnc_state "tactic-some-node"
: > "$ROOT/intentions/tactic-some-node.md"
printf 'needs a human decision' > "$JOB_DIR/office-hours-reason"
printf '1' > "$ROOT/park-exit"   # make the fake park-node exit non-zero
rc=$(stopnc_run)
assert_eq "stop: park-node failure → hook still exits 0" "0" "$rc"
assert_eq "stop: park-node failure → park-node was still attempted once" "1" "$(wc -l < "$ROOT/park-calls.log")"
stopnc_teardown

# ============================================================================
# dispatch-finalize-phase tests (#2243)
# ============================================================================
echo ""
echo "=== dispatch-finalize-phase ==="

# --- Test #2243-D2: finalize-phase spawns once + strips office-hours + self-closes last ---
# dispatch-finalize-phase calls siblings via its own $SCRIPT_DIR. To stub them,
# copy the real script into a fresh tmpdir alongside stub siblings in that same
# dir (the same pattern as dispatch-plan-finalize above). gh is on PATH from a
# dedicated bin/ subdir inside the tmpdir.

echo "Test: #2243 D2 dispatch-finalize-phase: spawn-once + office-hours removed from issue and PR + self-close last"
FINALIZE_TMPDIR=$(mktemp -d)
FINALIZE_STUB_DIR="$FINALIZE_TMPDIR/stub"
FINALIZE_BIN="$FINALIZE_TMPDIR/bin"
FINALIZE_SCRIPTS="$FINALIZE_TMPDIR/scripts"
mkdir -p "$FINALIZE_STUB_DIR" "$FINALIZE_BIN" "$FINALIZE_SCRIPTS"

# Copy the real finalize script into the scripts dir so $SCRIPT_DIR resolves there.
cp "$SCRIPT_DIR/dispatch-finalize-phase" "$FINALIZE_SCRIPTS/dispatch-finalize-phase"
chmod +x "$FINALIZE_SCRIPTS/dispatch-finalize-phase"
# dispatch-finalize-phase now `source`s lib.sh via $SCRIPT_DIR for the REST-backed
# gh helpers: gh_issue_remove_label_rest (the label mutation, #2256) and
# gh_issue_view_rest (the issue read, #2257). Copy lib.sh alongside it so the
# source resolves (this private tmpdir does not use the shared `setup`, which
# copies lib.sh).
cp "$SCRIPT_DIR/lib.sh" "$FINALIZE_SCRIPTS/lib.sh"

# Stub dispatch-spawn-tick: log to order.log and spawn-calls.log.
cat > "$FINALIZE_SCRIPTS/dispatch-spawn-tick" <<'STUB'
#!/usr/bin/env bash
echo "spawn" >> "$FINALIZE_STUB_DIR/order.log"
echo "spawn" >> "$FINALIZE_STUB_DIR/spawn-calls.log"
exit 0
STUB
chmod +x "$FINALIZE_SCRIPTS/dispatch-spawn-tick"

# Stub dispatch-spawn-sweep: log to sweep-calls.log (no order entry — mirrors stop harness).
cat > "$FINALIZE_SCRIPTS/dispatch-spawn-sweep" <<'STUB'
#!/usr/bin/env bash
echo "sweep" >> "$FINALIZE_STUB_DIR/sweep-calls.log"
exit 0
STUB
chmod +x "$FINALIZE_SCRIPTS/dispatch-spawn-sweep"

# Stub dispatch-self-close: log to order.log and self-close-calls.log.
cat > "$FINALIZE_SCRIPTS/dispatch-self-close" <<'STUB'
#!/usr/bin/env bash
echo "self-close" >> "$FINALIZE_STUB_DIR/order.log"
echo "self-close" >> "$FINALIZE_STUB_DIR/self-close-calls.log"
exit 0
STUB
chmod +x "$FINALIZE_SCRIPTS/dispatch-self-close"

# Stub gh: handle issue view (rate-limit labels — return empty) and the #2256
# REST DELETE label removals (gh api -X DELETE .../issues/<N>/labels/<name>). A PR
# is an issue in REST, so both the PR-456 and issue-123 office-hours removals hit
# the same issues/<N>/labels/<name> path; log every DELETE to one file and assert
# on the number. Return an empty body (success) so gh_issue_remove_label_rest's
# 404-tolerance branch is not triggered.
cat > "$FINALIZE_BIN/gh" <<'STUB'
#!/usr/bin/env bash
FINALIZE_STUB_DIR="$(cd "$(dirname "$0")/.." && pwd)/stub"
args="$*"
case "$args" in
  api\ repos/*/issues/*)
    # finalize-phase reads the issue via gh_issue_view_rest (#2257). Emit a raw-REST
    # object with no rate-limit-retry labels to clear (and a state so the helper's
    # .state|ascii_upcase does not error).
    printf '{"number":0,"state":"open","labels":[]}\n'
    ;;
  api\ -X\ DELETE\ */issues/*/labels/*)
    echo "$args" >> "$FINALIZE_STUB_DIR/gh-label-remove.log"
    echo '[]'
    ;;
  *)
    echo "gh stub: unknown invocation: $args" >&2
    exit 1
    ;;
esac
STUB
chmod +x "$FINALIZE_BIN/gh"

export PATH="$FINALIZE_BIN:$SAVED_PATH"
export FINALIZE_STUB_DIR
export CLAUDE_JOB_DIR="$FINALIZE_TMPDIR/job"
mkdir -p "$CLAUDE_JOB_DIR"

"$FINALIZE_SCRIPTS/dispatch-finalize-phase" 123 --pr 456
rc=$?
assert_eq "#2243 D2 dispatch-finalize-phase: exits 0" "0" "$rc"

# Assert office-hours REST-removed from the PR (issues/456/labels/dispatch:office-hours).
remove_log=$(cat "$FINALIZE_STUB_DIR/gh-label-remove.log" 2>/dev/null || true)
TOTAL=$((TOTAL + 1))
if [[ "$remove_log" == *"issues/456/labels/dispatch:office-hours"* ]]; then
  PASS=$((PASS + 1)); echo "  PASS: #2243 D2: REST DELETE dispatch:office-hours issued for PR 456"
else
  FAIL=$((FAIL + 1)); echo "  FAIL: #2243 D2: REST DELETE dispatch:office-hours issued for PR 456"
  echo "    gh-label-remove.log: $remove_log"
fi

# Assert office-hours REST-removed from the issue (issues/123/labels/dispatch:office-hours).
TOTAL=$((TOTAL + 1))
if [[ "$remove_log" == *"issues/123/labels/dispatch:office-hours"* ]]; then
  PASS=$((PASS + 1)); echo "  PASS: #2243 D2: REST DELETE dispatch:office-hours issued for issue 123"
else
  FAIL=$((FAIL + 1)); echo "  FAIL: #2243 D2: REST DELETE dispatch:office-hours issued for issue 123"
  echo "    gh-label-remove.log: $remove_log"
fi

# Assert spawn invoked exactly once.
spawn_calls=$(wc -l < "$FINALIZE_STUB_DIR/spawn-calls.log" 2>/dev/null || echo 0)
assert_eq "#2243 D2 dispatch-finalize-phase: spawn invoked exactly once" "1" "$spawn_calls"

# Assert sweep invoked.
TOTAL=$((TOTAL + 1))
if [[ -e "$FINALIZE_STUB_DIR/sweep-calls.log" ]]; then
  PASS=$((PASS + 1)); echo "  PASS: #2243 D2: sweep invoked"
else
  FAIL=$((FAIL + 1)); echo "  FAIL: #2243 D2: sweep invoked"
fi

# Assert self-close invoked.
TOTAL=$((TOTAL + 1))
if [[ -e "$FINALIZE_STUB_DIR/self-close-calls.log" ]]; then
  PASS=$((PASS + 1)); echo "  PASS: #2243 D2: self-close invoked"
else
  FAIL=$((FAIL + 1)); echo "  FAIL: #2243 D2: self-close invoked"
fi

# Assert self-close is LAST in order.log (spawn precedes self-close).
order_log=$(cat "$FINALIZE_STUB_DIR/order.log" 2>/dev/null || true)
last_entry=$(printf '%s' "$order_log" | tail -1)
TOTAL=$((TOTAL + 1))
if [[ "$last_entry" == "self-close" ]]; then
  PASS=$((PASS + 1)); echo "  PASS: #2243 D2: self-close is last in order.log"
else
  FAIL=$((FAIL + 1)); echo "  FAIL: #2243 D2: self-close is last in order.log"
  echo "    order.log: $order_log"
fi

