{
  "items": [
    {
      "id": "evt-declined",
      "status": "confirmed",
      "summary": "Declined meeting",
      "start": {"dateTime": "2026-05-26T16:00:00Z"},
      "end":   {"dateTime": "2026-05-26T17:00:00Z"},
