# --- --manual context-dependent fan-out (#1458) ------------------------------
# A bare human-typed /dispatch fans out enough workers to cover available graph
# work eagerly while honoring the MAX_WORKERS ceiling. It OVERRIDES the
# pace-curve throttle (a budget pause to TARGET_N=0 still fans out) but HONORS
# the --exhausted floor and the ceiling:
#   HEADROOM = max(0, MAX_WORKERS − LIVE_COUNT)
#   GAP      = max(0, TARGET_N − LIVE_COUNT)
#   SPAWN_N  = min(HEADROOM, max(GAP, 1))
# The legacy priority-LABELED bypass count (N_PRIO) died with the legacy
# selector, so N_PRIO is permanently 0 and SPAWN_N is driven by the pace-curve
# gap alone. SPAWN_N becomes the `--top` the graph selector fans out over: with a
# node available (SEL_GRAPH_TARGET), the tick emits a `graph` decision and
# graph-select-target is invoked `--top SPAWN_N` (logged to graph-select.log).
# Defaults are LIVE=0, MAX=8.

# Case 1: gap0. GAP=0 → SPAWN_N=min(8,max(0,1))=1 → graph --top 1.
echo "Test: select-tick --manual gap0 → graph fan-out --top 1"
sel_tick_setup
export SEL_TARGET_N=0 SEL_GRAPH_TARGET="node t1 tactic implement"
out=$(run_sel_tick --manual)
assert_eq "manual-gap0: graph decision" "graph 1 t1:tactic:implement" "$(printf '%s\n' "$out" | tail -n 1)"
assert_eq "manual-gap0: graph selector called --top 1 (floor)" "--top 1" "$(cat "$TMPDIR_TEST/logs/graph-select.log")"
sel_tick_teardown

# Case 2: gap5. TARGET_N=5, LIVE=0 → GAP=5 → SPAWN_N=min(8,max(5,1))=5 → --top 5.
echo "Test: select-tick --manual gap5 → graph fan-out --top 5"
sel_tick_setup
export SEL_TARGET_N=5 SEL_GRAPH_TARGET="node t1 tactic implement"
out=$(run_sel_tick --manual)
assert_eq "manual-gap5: graph selector called --top 5 (gap drives)" "--top 5" "$(cat "$TMPDIR_TEST/logs/graph-select.log")"
sel_tick_teardown

# Case 3: gap-clamped-to-headroom. LIVE=6, MAX=8 → HEADROOM=2; TARGET_N=10 →
# GAP=4 → SPAWN_N=min(2,max(4,1))=2. HEADROOM is the binding constraint.
echo "Test: select-tick --manual gap-clamped-to-headroom → graph --top 2"
sel_tick_setup
export SEL_LIVE_COUNT=6 SEL_TARGET_N=10 SEL_GRAPH_TARGET="node t1 tactic implement"
out=$(run_sel_tick --manual)
assert_eq "manual-gap-clamped: graph selector called --top 2 (headroom clamps gap)" "--top 2" "$(cat "$TMPDIR_TEST/logs/graph-select.log")"
sel_tick_teardown

# Case 4: at-max-live. LIVE=8 → HEADROOM=0 → concurrency-cap, lock released, NO
# reseed (a manual run is one-shot).
echo "Test: select-tick --manual at-max-live (HEADROOM=0) → concurrency-cap"
sel_tick_setup
export SEL_LIVE_COUNT=8 SEL_TARGET_N=1 SEL_GRAPH_TARGET="node t1 tactic implement"
out=$(run_sel_tick --manual)
assert_eq "manual-at-max-live: decision line" "concurrency-cap" "$(printf '%s\n' "$out" | tail -n 1)"
assert_eq "manual-at-max-live: lock released" "" "$(cat "$DISPATCH_LOCK_FILE")"
assert_eq "manual-at-max-live: no reseed" "0" \
  "$([ -f "$TMPDIR_TEST/logs/schedule-reseed.log" ] && echo 1 || echo 0)"
sel_tick_teardown

# Case 5: exhausted. --exhausted floor → concurrency-cap, lock released, NO reseed.
echo "Test: select-tick --manual exhausted → concurrency-cap, no reseed"
sel_tick_setup
export SEL_EXHAUSTED=exhausted SEL_TARGET_N=0 SEL_GRAPH_TARGET="node t1 tactic implement"
out=$(run_sel_tick --manual)
assert_eq "manual-exhausted: decision line" "concurrency-cap" "$(printf '%s\n' "$out" | tail -n 1)"
assert_eq "manual-exhausted: lock released" "" "$(cat "$DISPATCH_LOCK_FILE")"
assert_eq "manual-exhausted: no reseed" "0" \
  "$([ -f "$TMPDIR_TEST/logs/schedule-reseed.log" ] && echo 1 || echo 0)"
sel_tick_teardown

# Case 6: daemon-UNKNOWN. The busy-worker read fails → the manual math block is
# skipped (gated on that read succeeding) and GAP stays 1 (fail open) → --top 1.
echo "Test: select-tick --manual daemon-UNKNOWN → graph --top 1 (fail open)"
sel_tick_setup
export SEL_LIVE_COUNT_FAIL=1 SEL_GRAPH_TARGET="node t1 tactic implement"
out=$(run_sel_tick --manual)
assert_eq "manual-daemon-unknown: graph decision" "graph 1 t1:tactic:implement" "$(printf '%s\n' "$out" | tail -n 1)"
assert_eq "manual-daemon-unknown: graph selector called --top 1 (fail open)" "--top 1" "$(cat "$TMPDIR_TEST/logs/graph-select.log")"
sel_tick_teardown

# --- autonomous no-arg at cap, not exhausted, no priority item → concurrency-cap ---
# The exemption is --manual only. An autonomous no-arg tick at the budget with no
# priority/main-broken item waiting still emits concurrency-cap — unchanged hard
# cap — but the priority-only probe now runs (and returns empty) before it.
echo "Test: select-tick autonomous no-arg at cap, no priority item → concurrency-cap"
sel_tick_setup
export SEL_LIVE_COUNT=3 SEL_TARGET_N=0 SEL_EXHAUSTED=ok
out=$(run_sel_tick)
assert_eq "autonomous-cap: decision line is concurrency-cap" "concurrency-cap" \
  "$(printf '%s\n' "$out" | tail -n 1)"
assert_eq "autonomous-cap: lock released" "" "$(cat "$DISPATCH_LOCK_FILE")"
assert_eq "autonomous-cap: reseed scheduled" "called" \
  "$(cat "$TMPDIR_TEST/logs/schedule-reseed.log" 2>/dev/null)"
assert_eq "autonomous-cap: graph pace-exempt probe ran (returned empty)" "1" \
  "$([ -f "$TMPDIR_TEST/logs/graph-select-pace-exempt.log" ] && echo 1 || echo 0)"
sel_tick_teardown

# --- at cap, not exhausted, main-broken waiting → main-broken line, lock RELEASED ---
# A main that breaks WHILE at cap is now surfaced (the old early-exit fired before
# any selection ran). The diagnose bg job spawns lock-free downstream, so the lock
# is released here. No reseed.
echo "Test: select-tick at cap, main-broken → main-broken line, lock released, no reseed"
sel_tick_setup
export SEL_LIVE_COUNT=3 SEL_TARGET_N=1 SEL_EXHAUSTED=ok
# Graph pace-exempt lane empty; repo-health --main-broken-sha reports a red main
# (the at-cap main-broken bypass, Step 1b) → main-broken decision, spawned
# lock-free downstream.
export SEL_MAIN_BROKEN_SHA=deadbeef
out=$(run_sel_tick)
assert_eq "cap-mainbroken: decision line" "main-broken deadbeef" \
  "$(printf '%s\n' "$out" | tail -n 1)"
assert_eq "cap-mainbroken: lock released" "" "$(cat "$DISPATCH_LOCK_FILE")"
assert_eq "cap-mainbroken: no reseed scheduled" "0" \
  "$([ -f "$TMPDIR_TEST/logs/schedule-reseed.log" ] && echo 1 || echo 0)"
sel_tick_teardown

# --- at cap, EXHAUSTED → hard stop: concurrency-cap, no priority probe -------
# Genuine token exhaustion is the one hard floor: even with a priority item
# waiting, nothing spawns. The --priority-only probe is NOT consulted, the lock is
# released, the reseed is armed at the window reset, and the decision is
# concurrency-cap.
echo "Test: select-tick at cap, exhausted → concurrency-cap, no bypass probe consulted"
sel_tick_setup
export SEL_LIVE_COUNT=3 SEL_TARGET_N=1 SEL_EXHAUSTED=exhausted
# Even with a graph pace-exempt node available, genuine token exhaustion is the
# one hard floor: the tick short-circuits BEFORE the pace-exempt probe.
export SEL_GRAPH_PACE_EXEMPT="node tactic-p tactic implement"
out=$(run_sel_tick)
assert_eq "cap-exhausted: decision line" "concurrency-cap" \
  "$(printf '%s\n' "$out" | tail -n 1)"
assert_eq "cap-exhausted: lock released" "" "$(cat "$DISPATCH_LOCK_FILE")"
assert_eq "cap-exhausted: reseed scheduled" "called" \
  "$(cat "$TMPDIR_TEST/logs/schedule-reseed.log" 2>/dev/null)"
assert_eq "cap-exhausted: graph pace-exempt probe NOT consulted" "0" \
  "$([ -f "$TMPDIR_TEST/logs/graph-select-pace-exempt.log" ] && echo 1 || echo 0)"
sel_tick_teardown

# --- --manual + an explicit <number> → exit 2 (positional rejected outright) -
echo "Test: select-tick --manual + explicit number → exit 2"
sel_tick_setup
err=$("$TMPDIR_TEST/dispatch-select-tick" --manual 707 2>&1 1>/dev/null && echo "EXIT=0" || echo "EXIT=$?")
case "$err" in
  *"explicit issue/PR targeting"*"EXIT=2") status="ok" ;;
  *) status="bad: $err" ;;
esac
assert_eq "--manual + number → usage error, exit 2" "ok" "$status"
sel_tick_teardown

# --- AC3 non-fatal guarantee: unwritable log dir does NOT kill the tick -------
# Point DISPATCH_DECISION_LOG_DIR at a path that cannot be created (a sub-path of
# an existing regular file). The lib's mkdir -p will fail with ENOTDIR. The
# entire write body is wrapped in `{ ... } 2>/dev/null || true` so the failure is
# silently swallowed. Assert the tick still emits its normal terminal token and
# exits 0 — proving the non-fatal contract under set -uo pipefail.
echo "Test: select-tick decision-log write to unwritable dir is non-fatal (AC3)"
sel_tick_setup
# Use a blocker-file trick: touch a regular file, then point the log dir at a
# sub-path of it. mkdir -p /blocker/sub fails with ENOTDIR → write silently
# swallowed by the lib. The lib is STAGED (present in TMPDIR_TEST) so the only
# failure is the directory creation, not a missing decision_log_append function.
touch "$TMPDIR_TEST/decisionlog-blocker"
export DISPATCH_DECISION_LOG_DIR="$TMPDIR_TEST/decisionlog-blocker/sub"
out=$(run_sel_tick) ; rc=$?
assert_eq "AC3 nonfatal: tick exit 0 despite unwritable log dir" "0" "$rc"
assert_eq "AC3 nonfatal: terminal token is still empty" "empty" \
  "$(printf '%s\n' "$out" | tail -n 1)"
sel_tick_teardown

# ============================================================================
# === #1546: direct dispatch-escalate-sync-broken body-content tests ===
# ============================================================================
# Invokes the REAL dispatch-escalate-sync-broken (by absolute path) with git and
# gh PATH-shimmed. The git shim feeds fixed diagnostics; the gh shim captures the
# composed --title and --body-file contents so the test can inspect the body the
# script wrote. Exercises both the CREATE path (no open latch) and the EDIT path
# (an existing latch number), and the --reason parametrization (#1546).

ESB_SCRIPT="$SCRIPT_DIR/dispatch-escalate-sync-broken"
ESB_TMPDIR=""
ESB_CAPTURE=""
ESB_STUB_DIR=""

esb_setup() {
  ESB_TMPDIR=$(mktemp -d)
  ESB_CAPTURE="$ESB_TMPDIR/capture"
  # #2256: REST sentinel logs live alongside the capture dir. The gh stub records
  # the full argv of each `gh api` mutation here so the migrated PATCH/POST calls
  # can be asserted (mirrors the shared stub's gh-issue-*-rest-calls.log files).
  ESB_STUB_DIR="$ESB_TMPDIR/stub"
  mkdir -p "$ESB_TMPDIR/bin" "$ESB_CAPTURE" "$ESB_STUB_DIR"

  # git shim: fixed diagnostics for the three queries the script runs.
  cat > "$ESB_TMPDIR/bin/git" <<'STUB'
#!/usr/bin/env bash
case "$*" in
  "rev-parse --show-toplevel")          echo "/fake/main/worktree" ;;
  "status --porcelain")                 echo " M somefile" ;;
  "log --oneline origin/main..HEAD")    echo "deadbee some local commit" ;;
  *)                                    exit 0 ;;
esac
STUB
  chmod +x "$ESB_TMPDIR/bin/git"

  # gh shim: the script now drives the REST helpers gh_issue_edit_rest /
  # gh_issue_create_rest (#2256), which call `gh api -X PATCH|POST ... -f title=...
  # -F body=@<file>`. This stub (a) copies the body to capture/body.txt and the
  # title to capture/title.txt for the #1546 content assertions — keying on the
  # REST `-f title=` / `-F body=@` flags, NOT the old porcelain --title/--body-file
  # — and (b) logs each mutation's full argv to the shared REST sentinel files
  # (gh-issue-close-rest-calls.log for PATCH .../issues/<N>; gh-issue-create-rest-calls.log
  # for POST .../issues). `gh label create` is logged and exits 0 (or models
  # already-exists when $STUB_DIR/gh-label-exists is present). `gh api --paginate`
  # serves the find-or-create latch query (capture/existing.txt seeds an open latch).
  cat > "$ESB_TMPDIR/bin/gh" <<STUB
#!/usr/bin/env bash
CAP="$ESB_CAPTURE"
STUB_DIR="$ESB_STUB_DIR"
STUB
  cat >> "$ESB_TMPDIR/bin/gh" <<'STUB'
args="$*"
# Pull title=<val> (from `-f title=...`) and body=@<path> (from `-F body=@...`)
# out of the argv; capture their values for the body-content assertions.
for a in "$@"; do
  case "$a" in
    title=*)  printf '%s' "${a#title=}" > "$CAP/title.txt" ;;
    body=@*)  bf="${a#body=@}"; [[ -f "$bf" ]] && cat "$bf" > "$CAP/body.txt" ;;
  esac
done
case "$args" in
  "api --paginate"*)
    # gh_issue_list_rest uses REST: gh api --paginate repos/{owner}/{repo}/issues?...
    # Return the open-latch number if seeded; absent file means no open latch.
    # gh_issue_list_rest remaps from snake_case REST to camelCase; serve snake_case.
    if [[ -f "$CAP/existing.txt" ]]; then
      num=$(cat "$CAP/existing.txt")
      printf '[{"number":%s,"pull_request":null,"created_at":"2026-01-01T00:00:00Z","closed_at":null,"labels":[]}]' "$num"
    else
      echo '[]'
    fi
    exit 0
    ;;
  "api -X PATCH "*/issues/[0-9]*)
    # gh_issue_edit_rest sentinel: PATCH .../issues/<N> (EDIT path).
    echo "$args" >> "$STUB_DIR/gh-issue-close-rest-calls.log"
    echo '{}'
    ;;
  "api -X POST "*/issues\ *)
    # gh_issue_create_rest sentinel: POST .../issues (CREATE path). The helper pipes
    # the response through `jq -r .html_url`, so emit JSON carrying html_url; the
    # script's ${create_out##*/} then yields the bare trailing number (123).
    echo "$args" >> "$STUB_DIR/gh-issue-create-rest-calls.log"
    echo '{"html_url":"https://github.com/x/y/issues/123"}'
    ;;
  "label create"*)
    # Ensure-first latch-label create. Log the argv; model already-exists when the
    # marker is present (the script must tolerate it and still create the issue).
    echo "$args" >> "$STUB_DIR/gh-label-create.log"
    if [[ -f "$STUB_DIR/gh-label-exists" ]]; then
      echo "gh: Validation Failed (HTTP 422): already_exists" >&2
      exit 1
    fi
    if [[ -f "$STUB_DIR/gh-fail-label-create" ]]; then
      echo "gh: could not create label (HTTP 500): Internal Server Error" >&2
      exit 1
    fi
    ;;
  *)
    echo "gh stub (esb): unknown invocation: $*" >&2
    exit 1
    ;;
esac
STUB
  chmod +x "$ESB_TMPDIR/bin/gh"

  export PATH="$ESB_TMPDIR/bin:$SAVED_PATH"
  # Use plain mktemp inside the script (no CLAUDE_JOB_DIR tmp subtree needed).
  unset CLAUDE_JOB_DIR
}

esb_teardown() {
  export PATH="$SAVED_PATH"
  rm -rf "$ESB_TMPDIR"
  ESB_TMPDIR="" ; ESB_CAPTURE="" ; ESB_STUB_DIR=""
}

# Reset just the capture dir between runs within one setup.
esb_reset_capture() {
  rm -rf "$ESB_CAPTURE"
  mkdir -p "$ESB_CAPTURE"
}

# --- AC4 + AC3: fetch-failed body (CREATE path) ------------------------------
echo "Test: dispatch-escalate-sync-broken --reason fetch-failed body content (#1546)"
esb_setup
# No existing.txt → list returns empty → CREATE path.
ISSUE_NUM=$(printf '%s' "fatal: unable to access origin: Could not resolve host" \
  | "$ESB_SCRIPT" --reason fetch-failed) || ISSUE_NUM="ERR"
assert_eq "fetch-failed: issue number parsed from create URL" "123" "$ISSUE_NUM"
BODY=$(cat "$ESB_CAPTURE/body.txt" 2>/dev/null || true)
TITLE=$(cat "$ESB_CAPTURE/title.txt" 2>/dev/null || true)
assert_eq "fetch-failed body: states no merge was attempted" "1" \
  "$(grep -ciF 'no merge was attempted' <<<"$BODY" || true)"
assert_eq "fetch-failed body: no 'diverge' token" "0" \
  "$(grep -ic 'diverge' <<<"$BODY" || true)"
assert_eq "fetch-failed body: no 'conflict' token" "0" \
  "$(grep -ic 'conflict' <<<"$BODY" || true)"
assert_eq "fetch-failed body: no merge-stderr section header" "0" \
  "$(grep -cF 'git merge --ff-only origin/main (captured stderr)' <<<"$BODY" || true)"
assert_eq "fetch-failed body: no git-log divergence section" "0" \
  "$(grep -cF 'git log --oneline origin/main..HEAD' <<<"$BODY" || true)"
assert_eq "fetch-failed body: has fetch-stderr section header" "1" \
  "$(grep -cF '## git fetch origin main (captured stderr)' <<<"$BODY" || true)"
assert_eq "fetch-failed title: 'cannot reach origin/main'" "1" \
  "$(grep -cF 'cannot reach origin/main' <<<"$TITLE" || true)"
esb_teardown

# --- AC2: merge-failed body retains divergence language (CREATE path) ---------
echo "Test: dispatch-escalate-sync-broken --reason merge-failed body content (#1546)"
esb_setup
ISSUE_NUM=$(printf '%s' "CONFLICT (content): Merge conflict in foo" \
  | "$ESB_SCRIPT" --reason merge-failed) || ISSUE_NUM="ERR"
assert_eq "merge-failed: issue number parsed from create URL" "123" "$ISSUE_NUM"
BODY=$(cat "$ESB_CAPTURE/body.txt" 2>/dev/null || true)
TITLE=$(cat "$ESB_CAPTURE/title.txt" 2>/dev/null || true)
assert_eq "merge-failed body: has git-log divergence section" "1" \
  "$(grep -cF 'git log --oneline origin/main..HEAD (local divergence)' <<<"$BODY" || true)"
assert_eq "merge-failed body: has merge-stderr section header" "1" \
  "$(grep -cF 'git merge --ff-only origin/main (captured stderr)' <<<"$BODY" || true)"
assert_eq "merge-failed body: retains divergence language" "1" \
  "$([ "$(grep -ic diverge <<<"$BODY")" -ge 1 ] && echo 1 || echo 0)"
assert_eq "merge-failed title: 'cannot ff-merge origin/main'" "1" \
  "$(grep -cF 'cannot ff-merge origin/main' <<<"$TITLE" || true)"
esb_teardown

# --- Edit-path: --title is passed on the edit path too (existing latch) -------
echo "Test: dispatch-escalate-sync-broken edit path passes --title (#1546)"
esb_setup
printf '99\n' > "$ESB_CAPTURE/existing.txt"   # an open latch → EDIT path
EDIT_NUM=$(printf '%s' "fatal: unable to access origin" \
  | "$ESB_SCRIPT" --reason fetch-failed) || EDIT_NUM="ERR"
assert_eq "edit-path: existing issue number echoed" "99" "$EDIT_NUM"
TITLE=$(cat "$ESB_CAPTURE/title.txt" 2>/dev/null || true)
assert_eq "edit-path title: fetch-failed 'cannot reach origin/main'" "1" \
  "$(grep -cF 'cannot reach origin/main' <<<"$TITLE" || true)"
esb_teardown

# --- #2256: EDIT path fires a REST PATCH .../issues/<existing> carrying title+body
# The migrated edit drives gh_issue_edit_rest → `gh api -X PATCH repos/.../issues/99`.
# Assert the PATCH sentinel fired against the existing number, and that the title
# and body (from the --body-file the script composed) were both captured.
echo "Test: dispatch-escalate-sync-broken edit path → REST PATCH .../issues/<existing> (#2256)"
esb_setup
printf '99\n' > "$ESB_CAPTURE/existing.txt"   # an open latch → EDIT path
EDIT_NUM=$(printf '%s' "fatal: unable to access origin" \
  | "$ESB_SCRIPT" --reason fetch-failed) || EDIT_NUM="ERR"
assert_eq "edit-rest: existing issue number echoed" "99" "$EDIT_NUM"
EDIT_LOG="$ESB_STUB_DIR/gh-issue-close-rest-calls.log"
assert_eq "edit-rest: PATCH fired" "1" \
  "$([ -f "$EDIT_LOG" ] && grep -q 'PATCH' "$EDIT_LOG" && echo 1 || echo 0)"
assert_eq "edit-rest: PATCH targets issues/99" "1" \
  "$([ -f "$EDIT_LOG" ] && grep -q 'issues/99' "$EDIT_LOG" && echo 1 || echo 0)"
TITLE=$(cat "$ESB_CAPTURE/title.txt" 2>/dev/null || true)
BODY=$(cat "$ESB_CAPTURE/body.txt" 2>/dev/null || true)
assert_eq "edit-rest: PATCH carried the title" "1" \
  "$(grep -cF 'cannot reach origin/main' <<<"$TITLE" || true)"
assert_eq "edit-rest: PATCH carried the body (fetch-stderr section)" "1" \
  "$(grep -cF '## git fetch origin main (captured stderr)' <<<"$BODY" || true)"
esb_teardown

# --- #2256: CREATE path fires a REST POST .../issues with the latch labels -------
# The migrated create drives gh_issue_create_rest → `gh api -X POST repos/.../issues
# -f title=... -F body=@<file> -f labels[]=dispatch:sync-broken -f labels[]=bug
# -f labels[]=priority`. Assert the POST sentinel fired carrying body=@ (the
# --body-file flag) and all three labels, and that stdout is the parsed number.
echo "Test: dispatch-escalate-sync-broken create path → REST POST .../issues with labels (#2256)"
esb_setup
# No existing.txt → list empty → CREATE path. No gh-label-exists marker → label
# create succeeds.
ISSUE_NUM=$(printf '%s' "CONFLICT (content): Merge conflict in foo" \
  | "$ESB_SCRIPT" --reason merge-failed) || ISSUE_NUM="ERR"
assert_eq "create-rest: stdout is the parsed issue number" "123" "$ISSUE_NUM"
CREATE_LOG="$ESB_STUB_DIR/gh-issue-create-rest-calls.log"
assert_eq "create-rest: POST fired" "1" \
  "$([ -f "$CREATE_LOG" ] && grep -q 'POST' "$CREATE_LOG" && echo 1 || echo 0)"
assert_eq "create-rest: POST carried body=@ (--body-file)" "1" \
  "$([ -f "$CREATE_LOG" ] && grep -q -- '-F body=@' "$CREATE_LOG" && echo 1 || echo 0)"
assert_eq "create-rest: POST carried labels[]=dispatch:sync-broken" "1" \
  "$([ -f "$CREATE_LOG" ] && grep -q 'labels\[\]=dispatch:sync-broken' "$CREATE_LOG" && echo 1 || echo 0)"
assert_eq "create-rest: POST carried labels[]=bug" "1" \
  "$([ -f "$CREATE_LOG" ] && grep -q 'labels\[\]=bug' "$CREATE_LOG" && echo 1 || echo 0)"
assert_eq "create-rest: POST carried labels[]=priority" "1" \
  "$([ -f "$CREATE_LOG" ] && grep -q 'labels\[\]=priority' "$CREATE_LOG" && echo 1 || echo 0)"
esb_teardown

# --- #2256 REGRESSION GUARD: latch label initially ABSENT --------------------
# This is the exact regression this unit must not introduce: REST POST /issues
# silently drops an unknown label[], so the latch could be created WITHOUT its
# dispatch:sync-broken label. The ensure-first restructure prevents that by
# running `gh label create` BEFORE the create. With NO gh-label-exists marker the
# stub's `label create` SUCCEEDS (models the label being absent and then created);
# assert that (a) `gh label create dispatch:sync-broken` was invoked, and (b) the
# created issue STILL carries labels[]=dispatch:sync-broken in the POST.
echo "Test: dispatch-escalate-sync-broken create path with ABSENT latch label → label create + label retained (#2256)"
esb_setup
ISSUE_NUM=$(printf '%s' "CONFLICT (content): Merge conflict in foo" \
  | "$ESB_SCRIPT" --reason merge-failed) || ISSUE_NUM="ERR"
assert_eq "absent-label: create still succeeds (issue number)" "123" "$ISSUE_NUM"
LABEL_LOG="$ESB_STUB_DIR/gh-label-create.log"
assert_eq "absent-label: gh label create dispatch:sync-broken was invoked" "1" \
  "$([ -f "$LABEL_LOG" ] && grep -q 'label create dispatch:sync-broken' "$LABEL_LOG" && echo 1 || echo 0)"
CREATE_LOG="$ESB_STUB_DIR/gh-issue-create-rest-calls.log"
assert_eq "absent-label: created issue STILL carries labels[]=dispatch:sync-broken" "1" \
  "$([ -f "$CREATE_LOG" ] && grep -q 'labels\[\]=dispatch:sync-broken' "$CREATE_LOG" && echo 1 || echo 0)"
esb_teardown

# --- #2256: latch label ALREADY EXISTS → already-exists tolerated, no abort ----
# The ensure-first idiom tolerates only an already-exists error from `gh label
# create`. With the gh-label-exists marker the stub emits gh's already-exists
# message and exits 1; the script must NOT abort and must still create the issue
# with the latch label.
echo "Test: dispatch-escalate-sync-broken create path with already-exists latch label → tolerated (#2256)"
esb_setup
: > "$ESB_STUB_DIR/gh-label-exists"   # `gh label create` returns already-exists (exit 1)
ISSUE_NUM=$(printf '%s' "CONFLICT (content): Merge conflict in foo" \
  | "$ESB_SCRIPT" --reason merge-failed) || ISSUE_NUM="ERR"
assert_eq "already-exists: create still succeeds (issue number)" "123" "$ISSUE_NUM"
CREATE_LOG="$ESB_STUB_DIR/gh-issue-create-rest-calls.log"
assert_eq "already-exists: created issue carries labels[]=dispatch:sync-broken" "1" \
  "$([ -f "$CREATE_LOG" ] && grep -q 'labels\[\]=dispatch:sync-broken' "$CREATE_LOG" && echo 1 || echo 0)"
esb_teardown

# --- Invalid --reason → clear nonzero error ----------------------------------
echo "Test: dispatch-escalate-sync-broken --reason bogus → nonzero, clear message (#1546)"
esb_setup
if "$ESB_SCRIPT" --reason bogus </dev/null 2>"$ESB_CAPTURE/err.txt"; then rc=0; else rc=$?; fi
assert_eq "invalid --reason: nonzero exit" "1" "$([ "$rc" -ne 0 ] && echo 1 || echo 0)"
assert_eq "invalid --reason: clear message mentions reason" "1" \
  "$(grep -ic 'reason' "$ESB_CAPTURE/err.txt" || true)"
esb_teardown

# ============================================================================
# dispatch-tick tests (#982)
# ============================================================================
# The headless tick sequencer runs against FAKE dispatch-select-tick /
# dispatch-materialize-spawn / dispatch-spawn-job scripts (each landed in
# TMPDIR_TEST so dispatch-tick's SCRIPT_DIR resolution finds them). The fake
# select-tick prints a test-controlled decision line as its LAST stdout line; the
# fake materialize-spawn records its argv to a log file and prints a
# test-controlled terminal token; the fake spawn-job logs its argv. Each routing
# branch gets at least one assertion.
echo ""
echo "=== dispatch-tick ==="

tick_setup() {
  TMPDIR_TEST=$(mktemp -d)
  mkdir -p "$TMPDIR_TEST/logs"
  cp "$SCRIPT_DIR/dispatch-tick" "$TMPDIR_TEST/dispatch-tick"
  cp "$SCRIPT_DIR/lib.sh" "$TMPDIR_TEST/lib.sh"
  chmod +x "$TMPDIR_TEST/dispatch-tick"
  # Pin the canonical main worktree so the advisory diagnose-main / jit-reminder
  # spawns get a deterministic --cwd independent of the host repo layout and the
  # test's $PWD (dispatch-tick's resolve_project_root would otherwise resolve the
  # real project root). The fake spawn-job logs this value as its --cwd argv.
  export DISPATCH_TICK_MAIN_WORKTREE="$TMPDIR_TEST"
  # Pin the shared lock file under TMPDIR_TEST so the headless-liveness sentinel
  # (#1068) the tick writes resolves through dispatch_lock_file to a path inside
  # the test tree (not the host repo's tmp/).
  export DISPATCH_LOCK_FILE="$TMPDIR_TEST/dispatch.lock"

  # Fake dispatch-select-tick: echoes any TICK_SEL_PRE passthrough lines, then
  # the test-controlled decision line (TICK_DECISION) as the LAST line. Exits
  # TICK_SEL_RC (default 0).
  cat > "$TMPDIR_TEST/dispatch-select-tick" <<FAKE
#!/usr/bin/env bash
echo "\$*" >> "$TMPDIR_TEST/logs/select-tick.log"
echo "select" >> "$TMPDIR_TEST/logs/order.log"
[[ -n "\${TICK_SEL_PRE:-}" ]] && printf '%s\n' "\$TICK_SEL_PRE"
printf '%s\n' "\${TICK_DECISION:-empty}"
exit \${TICK_SEL_RC:-0}
FAKE
  # Fake dispatch-graph-execute (tactic-graph-router-selector): the ONLY queue
  # execute path now (the legacy dispatch-materialize-spawn lane was deleted in
  # Unit 3). Records its full argv (the id:kind:phase specs), echoes any
  # TICK_GRAPH_EXEC_PRE launch-narrative lines, then exits TICK_GRAPH_EXEC_RC
  # (default 0).
  cat > "$TMPDIR_TEST/dispatch-graph-execute" <<FAKE
#!/usr/bin/env bash
echo "\$*" >> "$TMPDIR_TEST/logs/graph-execute.log"
[[ -n "\${TICK_GRAPH_EXEC_PRE:-}" ]] && printf '%s\n' "\$TICK_GRAPH_EXEC_PRE"
exit \${TICK_GRAPH_EXEC_RC:-0}
FAKE
  # Fake dispatch-spawn-job: records its full argv, prints a spawn result.
  cat > "$TMPDIR_TEST/dispatch-spawn-job" <<FAKE
#!/usr/bin/env bash
echo "\$*" >> "$TMPDIR_TEST/logs/spawn-job.log"
echo "\${TICK_SPAWN_RESULT:-spawned}"
exit 0
FAKE
  # Fake dispatch-refresh-rate-limits (#1127): records that it ran (to order.log
  # for ordering assertions) and exits TICK_REFRESH_RC (default 0). The headless
  # tick runs this before the budget read; tests assert it runs first and that a
  # non-zero exit does not break the tick.
  cat > "$TMPDIR_TEST/dispatch-refresh-rate-limits" <<FAKE
#!/usr/bin/env bash
echo refresh >> "$TMPDIR_TEST/logs/order.log"
exit \${TICK_REFRESH_RC:-0}
FAKE
  # Fake dispatch-tick-recover (#1445): records that it ran so a test can assert
  # the no-spawn-drain backstop fired. Exits 0.
  cat > "$TMPDIR_TEST/dispatch-tick-recover" <<FAKE
#!/usr/bin/env bash
echo "recover" >> "$TMPDIR_TEST/logs/recover.log"
exit 0
FAKE
  # Fake dispatch-schedule-convergence-reseed (#1453): records each invocation so
  # a test can assert the convergence safety net was (or was NOT) armed on a
  # `propagate` token. Exits TICK_CONVERGE_RC (default 0). Same PATH-stub pattern
  # as the dispatch-spawn-job fake above.
  cat > "$TMPDIR_TEST/dispatch-schedule-convergence-reseed" <<FAKE
#!/usr/bin/env bash
echo "\$*" >> "$TMPDIR_TEST/logs/converge.log"
exit \${TICK_CONVERGE_RC:-0}
FAKE
  chmod +x "$TMPDIR_TEST/dispatch-select-tick" \
           "$TMPDIR_TEST/dispatch-graph-execute" \
           "$TMPDIR_TEST/dispatch-spawn-job" \
           "$TMPDIR_TEST/dispatch-refresh-rate-limits" \
           "$TMPDIR_TEST/dispatch-tick-recover" \
           "$TMPDIR_TEST/dispatch-schedule-convergence-reseed"
}

tick_teardown() {
  rm -rf "$TMPDIR_TEST"
  TMPDIR_TEST=""
  unset TICK_DECISION TICK_SEL_RC TICK_GRAPH_EXEC_RC \
    TICK_SEL_PRE TICK_GRAPH_EXEC_PRE TICK_SPAWN_RESULT DISPATCH_TICK_MAIN_WORKTREE \
    DISPATCH_LOCK_FILE TICK_REFRESH_RC TICK_CONVERGE_RC
}

run_tick() { "$TMPDIR_TEST/dispatch-tick" "$@" 2>/dev/null; }

# --- busy → exit 0, no graph-execute, no spawn-job -----------------------------
echo "Test: dispatch-tick busy → exit 0, no graph-execute/spawn"
tick_setup
export TICK_DECISION="busy"
out=$(run_tick) && rc=0 || rc=$?
assert_eq "busy: exit 0" "0" "$rc"
assert_eq "busy: no graph-execute call" "0" \
  "$([ -f "$TMPDIR_TEST/logs/graph-execute.log" ] && echo 1 || echo 0)"
assert_eq "busy: no spawn-job call" "0" \
  "$([ -f "$TMPDIR_TEST/logs/spawn-job.log" ] && echo 1 || echo 0)"
tick_teardown

# --- concurrency-cap / sync-repair-pending / sync-broken ---------------------
# Pass-through dispositions: exit 0, no graph-execute, no spawn-job. #1495 adds
# the two sync pass-throughs (sync-repair-pending, sync-broken); sync-failed moved
# out of this loop because it now spawns the repair job (covered below). `empty`
# moved out because #1557 routes it through dispatch-tick-recover on the
# autonomous path (covered by its own tests below). The legacy `resolver-failed`
# disposition died with the legacy selector — it is now an unrecognized decision.
for d in concurrency-cap sync-repair-pending sync-broken; do
  echo "Test: dispatch-tick $d → exit 0, no graph-execute/spawn"
  tick_setup
  export TICK_DECISION="$d"
  out=$(run_tick) && rc=0 || rc=$?
  assert_eq "$d: exit 0" "0" "$rc"
  assert_eq "$d: no graph-execute call" "0" \
    "$([ -f "$TMPDIR_TEST/logs/graph-execute.log" ] && echo 1 || echo 0)"
  assert_eq "$d: no spawn-job call" "0" \
    "$([ -f "$TMPDIR_TEST/logs/spawn-job.log" ] && echo 1 || echo 0)"
  tick_teardown
done

# --- main-broken → spawn-job /dispatch-diagnose-main, exit 0 -----------------
echo "Test: dispatch-tick main-broken → spawn-job diagnose-main"
tick_setup
export TICK_DECISION="main-broken abc1234"
out=$(run_tick) && rc=0 || rc=$?
assert_eq "main-broken: exit 0" "0" "$rc"
assert_eq "main-broken: spawn-job argv (Sonnet — diagnosis authors no product code)" \
  "--name diagnose-main --cwd $TMPDIR_TEST --model sonnet /dispatch-diagnose-main abc1234" \
  "$(cat "$TMPDIR_TEST/logs/spawn-job.log")"
assert_eq "main-broken: no graph-execute call" "0" \
  "$([ -f "$TMPDIR_TEST/logs/graph-execute.log" ] && echo 1 || echo 0)"
tick_teardown

# --- #1495: sync-failed → spawn-job /commit-merge-push (sync-repair), exit 0 ---
echo "Test: dispatch-tick sync-failed → spawn-job sync-repair /commit-merge-push"
tick_setup
export TICK_DECISION="sync-failed"
out=$(run_tick) && rc=0 || rc=$?
assert_eq "sync-failed: exit 0" "0" "$rc"
assert_eq "sync-failed: spawn-job argv (Sonnet — conflict recovery escalates to Opus internally)" \
  "--name sync-repair --cwd $TMPDIR_TEST --model sonnet /commit-merge-push" \
  "$(cat "$TMPDIR_TEST/logs/spawn-job.log")"
assert_eq "sync-failed: no graph-execute call" "0" \
  "$([ -f "$TMPDIR_TEST/logs/graph-execute.log" ] && echo 1 || echo 0)"
tick_teardown

# --- jit-reminder → spawn-job /dispatch-jit-reminder, exit 0 -----------------
echo "Test: dispatch-tick jit-reminder → spawn-job jit-reminder-<num>"
tick_setup
export TICK_DECISION="jit-reminder owner/repo 42 PVT_x ITEM_y"
out=$(run_tick) && rc=0 || rc=$?
assert_eq "jit-reminder: exit 0" "0" "$rc"
assert_eq "jit-reminder: spawn-job argv (Sonnet — reminder skills author no product code)" \
  "--name jit-reminder-42 --cwd $TMPDIR_TEST --model sonnet /dispatch-jit-reminder owner/repo 42 PVT_x ITEM_y" \
  "$(cat "$TMPDIR_TEST/logs/spawn-job.log")"
tick_teardown

# --- graph <count> <spec>... → dispatch-graph-execute <spec>..., exit 0 ------
# The graph lane is the ONLY queue execute path now. dispatch-tick shifts off the
# `graph` keyword and the <count>, then hands the id:kind:phase specs to
# dispatch-graph-execute. The per-node reservations are already written and the
# lock already released by select-tick, so the execute runs lock-free.
echo "Test: dispatch-tick graph → dispatch-graph-execute with the node specs"
tick_setup
export TICK_DECISION="graph 2 t1:tactic:implement t2:tactic:review"
out=$(run_tick) && rc=0 || rc=$?
assert_eq "graph-exec: exit 0" "0" "$rc"
assert_eq "graph-exec: graph-execute got the specs (count/keyword stripped)" \
  "t1:tactic:implement t2:tactic:review" "$(cat "$TMPDIR_TEST/logs/graph-execute.log")"
assert_eq "graph-exec: no spawn-job call (graph lane spawns via graph-execute)" "0" \
  "$([ -f "$TMPDIR_TEST/logs/spawn-job.log" ] && echo 1 || echo 0)"
tick_teardown

# --- #1453: convergence reseed armed on a graph execute (autonomous only) -----
# On a `graph` decision from an AUTONOMOUS tick (no --manual, no explicit <N>),
# dispatch-tick calls dispatch-schedule-convergence-reseed exactly once after the
# execute. The autonomous-only guard keys on the $MANUAL/$ARG globals, NOT the
# decision string: the --manual test below sets that global through the real
# invocation (--manual trips MANUAL). The graph lane is the only queue execute
# path now (the legacy issue/pr/materialize lane was deleted in Unit 3).
echo "Test: dispatch-tick autonomous graph → convergence reseed armed once (#1453)"
tick_setup
export TICK_DECISION="graph 1 t1:tactic:implement"
out=$(run_tick) && rc=0 || rc=$?
assert_eq "converge-graph: exit 0" "0" "$rc"
assert_eq "converge-graph: convergence script called exactly once" "1" \
  "$(wc -l < "$TMPDIR_TEST/logs/converge.log" | tr -d ' ')"
tick_teardown

echo "Test: dispatch-tick --manual graph → convergence reseed NOT armed (autonomous-only) (#1453)"
tick_setup
export TICK_DECISION="graph 1 t1:tactic:implement"
out=$(run_tick --manual) && rc=0 || rc=$?
assert_eq "converge-manual: exit 0" "0" "$rc"
assert_eq "converge-manual: convergence script NOT called (MANUAL set)" "0" \
  "$([ -f "$TMPDIR_TEST/logs/converge.log" ] && echo 1 || echo 0)"
tick_teardown

echo "Test: dispatch-tick convergence reseed failure is best-effort → tick still exits 0 (#1453)"
tick_setup
export TICK_DECISION="graph 1 t1:tactic:implement" TICK_CONVERGE_RC=1
out=$(run_tick) && rc=0 || rc=$?
assert_eq "converge-besteffort: exit 0 despite arm failure" "0" "$rc"
assert_eq "converge-besteffort: convergence script was called" "1" \
  "$(wc -l < "$TMPDIR_TEST/logs/converge.log" | tr -d ' ')"
tick_teardown

echo "Test: dispatch-tick concurrency-cap → convergence reseed NOT armed (#1453)"
tick_setup
export TICK_DECISION="concurrency-cap"
out=$(run_tick) && rc=0 || rc=$?
assert_eq "converge-cap: exit 0" "0" "$rc"
assert_eq "converge-cap: convergence script NOT called (no propagate branch)" "0" \
  "$([ -f "$TMPDIR_TEST/logs/converge.log" ] && echo 1 || echo 0)"
tick_teardown

echo "Test: dispatch-tick autonomous empty → invokes recover, exit 0 (#1557)"
tick_setup
export TICK_DECISION="empty"
out=$(run_tick) && rc=0 || rc=$?
assert_eq "empty: exit 0" "0" "$rc"
assert_eq "empty: recover invoked" "1" \
  "$([ -f "$TMPDIR_TEST/logs/recover.log" ] && echo 1 || echo 0)"
assert_eq "empty: no graph-execute call" "0" \
  "$([ -f "$TMPDIR_TEST/logs/graph-execute.log" ] && echo 1 || echo 0)"
