echo "Test: dispatch-tick unrecognized decision → exit 2"
tick_setup
export TICK_DECISION="garbage unexpected"
out=$(run_tick) && rc=0 || rc=$?
assert_eq "unrecognized: exit 2" "2" "$rc"
assert_eq "unrecognized: no graph-execute call" "0" \
