# --- unknown flag → usage error, exit 2 --------------------------------------
echo "Test: dispatch-tick unknown flag → exit 2"
tick_setup
err=$("$TMPDIR_TEST/dispatch-tick" --nope 2>&1 1>/dev/null && echo "EXIT=0" || echo "EXIT=$?")
case "$err" in
