chmod +x "$TMPDIR_TEST/fix/fake-writer"
printf '%s\n' '{"five_hour":{"used_percentage":4,"resets_at":1780867800},"seven_day":{"used_percentage":84,"resets_at":1780880400}}' \
  > "$TMPDIR_TEST/fix/rate_limits.json"
