TOTAL=$((TOTAL + 1))
if [[ "$log" == *"/dispatch-resume-worker worker-name /work/cwd sess-abc"* ]]; then
  PASS=$((PASS + 1)); echo "  PASS: empty-model ExecStart carries <name> <cwd> <sessionId>"
else
